const lesson = (title, objective, explanation, practice, scenario, risks, activity) => ({
  title,
  content: `LEARNING OBJECTIVE
${objective}

CORE EXPLANATION
${explanation}

WORKPLACE PRACTICE
${practice}

REALISTIC WORKPLACE EXAMPLE
${scenario}

COMMON MISTAKES AND RISKS
${risks}

LEARNER ACTIVITY
${activity}

PRACTICAL CHECK
Before finishing, explain the key decision in your own words, identify who should be involved, and name the record or approved process that supports the action. Apply the same care when working remotely, across time zones, or with colleagues from different backgrounds. If a situation is urgent or outside your authority, pause and use the organisation's escalation route rather than improvising. Keep notes factual, proportionate, and limited to people who need the information. `
});

const makeQuestions = (rows) => rows.map((row, index) => ({
  id: `question-${index + 1}`,
  text: row[0],
  options: row.slice(1, 5),
  correctIndex: row[5],
}));

